import { test, expect } from '@playwright/test';

test.describe('File Upload - File Name and Size Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display file name and size after selecting a file', async ({ page }) => {
    // Setup: intercept the file upload API
    await page.route('**/api/files/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Locate and click the file input using getByLabel
    const fileInput = page.getByLabel('Select a file');
    await fileInput.click();

    // Setup: intercept the file upload API
    await page.route('**/api/files/upload', (route) => {
      route.continue();
    });

    // Setup: intercept the file upload response
    await page.route('**/api/files/upload', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          success: true,
          fileName: 'document.pdf',
          fileSize: 12549,
          mimeType: 'application/pdf'
        }),
      });
    });

    // Wait for the file input to be ready
    await page.waitForTimeout(100);

    // Verify file name and size are displayed
    const fileNameDisplay = page.getByText('document.pdf');
    await expect(fileNameDisplay).toBeVisible();

    const fileSizeDisplay = page.getByText('12.5 KB');
    await expect(fileSizeDisplay).toBeVisible();

    // Verify the file size is formatted correctly
    const sizeText = await fileSizeDisplay.textContent();
    expect(sizeText).toContain('12.5 KB');

    // Verify the file name is displayed in the file list
    const fileList = page.getByRole('list');
    await expect(fileList).toContainText('document.pdf');
  });

  test('should handle file selection with error and not display file details', async ({ page }) => {
    // Setup: intercept the file upload API and return an error
    await page.route('**/api/files/upload', (route) => {
      route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({
          success: false,
          error: 'Server error during upload'
        }),
      });
    });

    // Locate and click the file input using getByLabel
    const fileInput = page.getByLabel('Select a file');
    await fileInput.click();

    // Setup: intercept the file upload response
    await page.route('**/api/files/upload', (route) => {
      route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({
          success: false,
          error: 'Server error during upload'
        }),
      });
    });

    // Wait for the file upload to complete
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText('Server error during upload');
    await expect(errorMessage).toBeVisible();

    // Verify file name and size are NOT displayed
    const fileNameDisplay = page.getByText('document.pdf');
    await expect(fileNameDisplay).not.toBeVisible();

    const fileSizeDisplay = page.getByText('12.5 KB');
    await expect(fileSizeDisplay).not.toBeVisible();

    // Verify the file list is empty
    const fileList = page.getByRole('list');
    await expect(fileList).not.toContainText('document.pdf');
  });
});
